package gateway

import (
	"crypto/rand"
	"encoding/hex"
	"net/url"
	"regexp"
	"strconv"
	"strings"
	"unicode"

	"github.com/optimiware/kodama/internal/domain"
)

// RequestID identifies one admitted model request. It is generated by the
// gateway, never taken from a workload.
type RequestID string

// NewRequestID draws 128 random bits.
func NewRequestID() (RequestID, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", FailWith(ErrUnavailable, err, "no randomness available")
	}
	return RequestID("mrq_" + hex.EncodeToString(b)), nil
}

// Validate checks the shared identifier syntax.
func (r RequestID) Validate() error {
	if err := domain.RunID(r).Validate(); err != nil {
		return fail(ErrInvalid, "the request identifier is malformed")
	}
	return nil
}

var (
	secretRefPattern = regexp.MustCompile(`^secret://project/[a-z][a-z0-9-]{0,62}$`)
	modelPattern     = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._:/@-]{0,127}$`)
	codePattern      = regexp.MustCompile(`^[a-z][a-z0-9_]{0,63}$`)
	hostPattern      = regexp.MustCompile(`^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$`)
	pathPattern      = regexp.MustCompile(`^/[A-Za-z0-9._~/-]{0,254}$`)
)

// ValidModelName reports whether s is an acceptable model identifier.
func ValidModelName(s string) bool { return modelPattern.MatchString(s) }

// ValidCode reports whether s is a stable lowercase reason code.
func ValidCode(s string) bool { return codePattern.MatchString(s) }

// Hard ceilings of the policy values. They exist so no configuration or
// arithmetic can overflow the 2^53-1 integers every counter and contract uses.
const (
	MaxModels          = 32
	MaxRequestsCeiling = 100_000
	MaxBytesCeiling    = 4 << 20
	MaxInputCeiling    = 4_000_000
	MaxOutputCeiling   = 1_000_000
	MaxAllowance       = 1 << 40
)

// Endpoint is an approved base URL of an OpenAI-compatible provider: HTTPS, a
// host and optional port, a restricted path, no credentials, query or fragment.
// Approval of the origin is a separate decision (Destinations); this type only
// guarantees a well-formed, normalized value.
type Endpoint struct {
	scheme string
	host   string
	port   int
	path   string
}

// ParseEndpoint validates and normalizes a base URL. The host is lower-cased,
// the default port is dropped and a trailing slash is removed.
func ParseEndpoint(raw string) (Endpoint, error) {
	if len(raw) == 0 || len(raw) > 512 {
		return Endpoint{}, fail(ErrInvalid, "the endpoint must be 1 to 512 characters")
	}
	for _, r := range raw {
		if unicode.IsControl(r) || unicode.IsSpace(r) || r > unicode.MaxASCII {
			return Endpoint{}, fail(ErrInvalid, "the endpoint must be printable ASCII")
		}
	}
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" {
		return Endpoint{}, fail(ErrInvalid, "the endpoint must be an https URL")
	}
	if u.User != nil || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" || u.Opaque != "" || u.RawPath != "" {
		return Endpoint{}, fail(ErrInvalid, "the endpoint must not carry credentials, a query, a fragment or encoded path characters")
	}
	// IPv6 literals are not accepted: a hostname or IPv4 literal only.
	host := strings.ToLower(u.Hostname())
	if !hostPattern.MatchString(host) {
		return Endpoint{}, fail(ErrInvalid, "the endpoint host is not valid")
	}
	port := 443
	if p := u.Port(); p != "" {
		n, err := strconv.Atoi(p)
		if err != nil || n < 1 || n > 65535 {
			return Endpoint{}, fail(ErrInvalid, "the endpoint port is not valid")
		}
		port = n
	}
	path := strings.TrimSuffix(u.Path, "/")
	if path != "" && (!pathPattern.MatchString(path) || strings.Contains(path, "//") || hasDotSegment(path)) {
		return Endpoint{}, fail(ErrInvalid, "the endpoint path is not valid")
	}
	return Endpoint{scheme: "https", host: host, port: port, path: path}, nil
}

func hasDotSegment(p string) bool {
	for _, s := range strings.Split(p, "/") {
		if s == "." || s == ".." {
			return true
		}
	}
	return false
}

// IsZero reports an unset endpoint.
func (e Endpoint) IsZero() bool { return e.host == "" }

// Host is the lower-case host name or IPv4 literal.
func (e Endpoint) Host() string { return e.host }

// Port is the TCP port (443 by default).
func (e Endpoint) Port() int { return e.port }

// Path is the base path without a trailing slash ("" for the root).
func (e Endpoint) Path() string { return e.path }

// Origin is the scheme, host and non-default port: the audience a credential is
// bound to.
func (e Endpoint) Origin() string {
	if e.port == 443 {
		return "https://" + e.host
	}
	return "https://" + e.host + ":" + strconv.Itoa(e.port)
}

// String is the normalized base URL.
func (e Endpoint) String() string { return e.Origin() + e.path }

// ChatURL is the chat completions URL below the base path.
func (e Endpoint) ChatURL() string { return e.String() + "/chat/completions" }

// CredentialRef pins one exact version of a project secret.
type CredentialRef struct {
	Ref     string
	Version int64
}

// Validate checks the reference form and version.
func (c CredentialRef) Validate() error {
	if !secretRefPattern.MatchString(c.Ref) {
		return fail(ErrInvalid, "the credential must be secret://project/<name>")
	}
	if c.Version < 1 || c.Version > domain.MaxSafeInteger {
		return fail(ErrInvalid, "the credential version must be a positive integer")
	}
	return nil
}

// Name is the secret name of the reference.
func (c CredentialRef) Name() string { return strings.TrimPrefix(c.Ref, "secret://project/") }

// Limits are the bounded allowances of one run.
type Limits struct {
	// MaxRequests is the number of model requests a run may admit.
	MaxRequests int64
	// TokenAllowance stops new admission once charged tokens reach it.
	TokenAllowance int64
	// MaxRequestBytes bounds the size of one request body.
	MaxRequestBytes int64
	// MaxInputTokens bounds the conservative input estimate of one request.
	MaxInputTokens int64
	// MaxOutputTokens bounds the output tokens one request may ask for.
	MaxOutputTokens int64
}

// Validate checks every bound against its ceiling.
func (l Limits) Validate() error {
	in := func(name string, v, hi int64) error {
		if v < 1 || v > hi {
			return fail(ErrInvalid, "%s must be between 1 and %d", name, hi)
		}
		return nil
	}
	for _, err := range []error{
		in("maxRequests", l.MaxRequests, MaxRequestsCeiling), in("tokenAllowance", l.TokenAllowance, MaxAllowance),
		in("maxRequestBytes", l.MaxRequestBytes, MaxBytesCeiling), in("maxInputTokens", l.MaxInputTokens, MaxInputCeiling),
		in("maxOutputTokens", l.MaxOutputTokens, MaxOutputCeiling),
	} {
		if err != nil {
			return err
		}
	}
	return nil
}

// RequestBound is Bmax: the most tokens one request is ever charged when its
// usage is unknown, and therefore the published overshoot of the allowance.
func (l Limits) RequestBound() int64 { return l.MaxInputTokens + l.MaxOutputTokens }

// Overshoot is the published bound: charged tokens never exceed
// TokenAllowance - 1 + RequestBound unless the provider reports usage above the
// verified bounds, which is a protocol failure (see protocol.md).
func (l Limits) Overshoot() int64 { return l.RequestBound() }
